import sys

def count_unique_colors(arr, start, end):
    visited_colors = [False] * 24
    count = 0
    for i in range(start, end + 1):
        color = arr[i]
        if not visited_colors[color]:
            visited_colors[color] = True
            count += 1
    return count

def main():
    input_line = sys.stdin.readline().strip()
    a, b, l, r = map(int, input_line.split())
    l -= 1
    r -= 1

    total_segments = a + b
    repeat_times = 4
    pattern = [0] * (total_segments * repeat_times)

    segment_offset = l // total_segments
    l -= segment_offset * total_segments
    r -= segment_offset * total_segments

    segment_length = (r - l + 1) // total_segments
    if segment_length > 2:
        r -= (segment_length - 2) * total_segments

    delta = a - b if a > b else 1

    for i in range(repeat_times):
        for k in range(a - delta):
            pattern[(a + b) * i + k] = k
        for k in range(delta):
            pattern[(a + b) * i + a - delta + k] = (a - delta + k) if i % 2 == 0 else a + k

    min_colors = a + a
    for shiftA in range(1, delta + 1):
        for k in range(b):
            pattern[(a + b) * 0 + a + k] = pattern[(a + b) * 0 + a - shiftA]
        for shiftB in range(1, delta + 1):
            for k in range(b):
                pattern[(a + b) * 1 + a + k] = pattern[(a + b) * 1 + a - shiftB]
            for shiftC in range(1, delta + 1):
                for k in range(b):
                    pattern[(a + b) * 2 + a + k] = pattern[(a + b) * 2 + a - shiftC]
                for k in range(b):
                    pattern[(a + b) * 3 + a + k] = pattern[(a + b) * 3 + a - shiftC]
                min_colors = min(min_colors, count_unique_colors(pattern, l, r))
    print(min_colors)

if __name__ == "__main__":
    main()

